var a=`0998-pad-thai`;var n=`world-0998`;var s=`TH`;var t=`southeast-asia`;var r=4;var o=45;var d={en:`Pad Thai`,ua:`Пад тай`};var g={en:`Pad Thai is a Thailand dish made with rice noodles, tamarind concentrate, fish sauce, shrimp. This home-scale recipe assigns measured ingredients to the steps where they are used. Roast peanuts before garnishing. Cook shrimp and egg fully.`,ua:`Пад тай, страва кухні країни Таїланд. Основні складники: рисова локшина, концентрат тамаринду, рибний соус, креветка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Підсмажте арахіс перед подаванням; креветки й яйця доведіть до повної готовності.`};var u=[{en:`Soak the listed rice, grains or noodles in clean water for about 18 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 18 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`soaking-dried-produce`],m:18,i:[[`rice-noodles`,370,`g`],[`water`,800,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`tamarind-concentrate`,70,`g`],[`palm-sugar`,70,`g`],[`fish-sauce`,65,`ml`],[`water`,80,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`shrimp`,330,`g`],[`tofu-firm`,210,`g`],[`shallot`,140,`g`],[`garlic`,4,`clove`],[`peanut-oil`,55,`ml`]]},{en:`Quickly fry soaked noodles in tamarind sauce with cooked shrimp, tofu, egg and bean sprouts; toss until the sauce is absorbed.`,ua:`Швидко смажте замочену локшину в тамариндовому соусі з готовими креветками, тофу, яйцем і паростками, доки соус не вбереться.`,t:[`pan-frying`],m:9,i:[[`chicken-egg`,3,`pcs`],[`bean-sprouts`,230,`g`],[`chives`,100,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut`,85,`g`],[`lime`,2,`pcs`]]}];var h={slug:a,id:n,country:`TH`,region:t,servings:4,minutes:45,title:d,text:g,steps:u};export{s as country,h as default,n as id,o as minutes,t as region,r as servings,a as slug,u as steps,g as text,d as title};